query HomeKpis($range: DateRange!) {
  merchant {
    id
    displayName
    kpis(range: $range) {
      grossVolume { amount currency }
      netVolume { amount currency }
      successfulPayments
      disputeRate
    }
  }
}

query RecentPayments($first: Int = 20, $after: String) {
  payments(first: $first, after: $after, orderBy: CREATED_AT_DESC) {
    edges {
      node { id amount { amount currency } status customer { name email } createdAt }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query UpcomingPayouts {
  payouts(filter: { status: [PENDING, IN_TRANSIT] }) {
    id
    amount { amount currency }
    arrivalDate
    destination { bankName last4 }
  }
}

mutation UpdatePayoutSchedule($input: PayoutScheduleInput!) {
  updatePayoutSchedule(input: $input) {
    schedule { interval weeklyAnchor delayDays }
    errors { field message }
  }
}

mutation InviteTeammate($email: String!, $role: TeamRole!) {
  inviteTeammate(email: $email, role: $role) {
    invitation { id email role expiresAt }
  }
}

subscription OnPaymentUpdated($merchantId: ID!) {
  paymentUpdated(merchantId: $merchantId) { id status updatedAt }
}

query IntrospectionQuery {
  __schema {
    queryType { name }
    mutationType { name }
    types { name kind }
  }
}

